const u = $input.first().json;
const m = u.message || null;
const cb = u.callback_query || null;
let kind = 'other', text = '', file_id = '', chat_id = 0, from_id = 0, cb_id = '', cb_data = '', message_id = 0;
if (cb) {
  kind = 'callback'; chat_id = cb.message.chat.id; from_id = cb.from.id; cb_id = cb.id; cb_data = cb.data || ''; message_id = cb.message.message_id;
} else if (m) {
  chat_id = m.chat.id; from_id = m.from.id; message_id = m.message_id;
  if (m.voice || m.audio) { kind = 'voice'; file_id = (m.voice || m.audio).file_id; }
  else if (Array.isArray(m.photo) && m.photo.length) { kind = 'photo'; file_id = m.photo[m.photo.length - 1].file_id; text = m.caption || ''; }
  else if (typeof m.text === 'string') { text = m.text; kind = text.startsWith('/') ? 'command' : 'text'; }
}
return [{ json: { update_id: u.update_id, kind: kind, chat_id: chat_id, from_id: from_id, text: text, file_id: file_id, cb_id: cb_id, cb_data: cb_data, message_id: message_id } }];

const n = Number(Object.values($input.first().json)[0]);
const base = $('Normalizar update').first().json;
return [{ json: Object.assign({}, base, { duplicado: n > 1 }) }];

const r = $input.first().json.r || {};
const u = $('Normalizar update').first().json;
return [{ json: { chat_id: u.chat_id, text: r.text || 'Ok.', kb: r.kb || 'none', rid: r.rid || 0, state: r.state || '' } }];

const r = $input.first().json;
let text = String(r.text || 'Ok.');
if (text.length > 3900) { text = text.slice(0, 3900) + '...'; }
return [{ json: { chat_id: r.chat_id, text: text, kb: r.kb || 'none', rid: r.rid || 0, state: r.state || '' } }];

const u = $('Normalizar update').first().json;
const user = $('Buscar usuario').first().json;
const NL = String.fromCharCode(10);
const cmd = (u.text.split(' ')[0] || '').split('@')[0].toLowerCase();
let text = '', kb = 'none';
if (cmd === '/start') {
  text = ['Oi, ' + user.name + '! Eu sou o seu assistente pessoal aqui no Telegram. Cuido de lembretes, agenda, tarefas e itens que acabam, e entendo texto, audio e fotos. Eu lembro do que conversamos, entao pode responder as minhas perguntas em mensagens separadas.', '',
    'Exemplos do que voce pode me dizer:',
    '1) (audio ou texto) "me lembre amanha as 9h de passar no mercado"',
    '2) "tenho cartorio quinta as 14:30, me lembre 1h antes" (crio na sua agenda)',
    '3) "o que tenho hoje?" ou "o que tenho essa semana?"',
    '4) "sempre me avise 30 min antes dos compromissos"',
    '5) Remedio: "me lembre de tomar losartana todo dia as 8h". Eu aviso na hora e repito a cada 10 minutos ate voce tocar Tomei. Pode mandar uma foto da cartela que eu leio o nome e quantos comprimidos restam. Quando estiver acabando, o aviso de compra vem no resumo da manha ate voce dizer "comprei".',
    '6) Tarefas (Google Tasks): "anota na lista: ligar pro contador", "o que tenho nas tarefas?", "conclui a tarefa do contador".', '',
    'Privacidade: para entender suas mensagens e fotos eu uso o Gemini, do Google, entao o conteudo delas passa por la.', '',
    'Comandos: /config (suas preferencias) e /ajuda.', '',
    'Para comecar: a que horas voce quer receber o resumo da manha?'].join(NL);
  kb = 'summary_time';
} else if (cmd === '/ajuda' || cmd === '/help') {
  text = ['Eu entendo texto, audio e fotos, e lembro das ultimas mensagens da conversa. Exemplos:',
    '- "me lembre amanha as 15h de ligar para o contador"',
    '- "reuniao sexta as 10h, me lembre 1h antes"',
    '- "o que tenho hoje?" / "amanha?" / "essa semana?"',
    '- "lembra nos dois de comprar pao as 18h" (aviso para voce e para a outra pessoa)',
    '- "me lembre de tomar a vitamina D todo dia as 8h" (ja cadastra) / "tomei a vitamina D" / "comprei a vitamina D"',
    '- foto da cartela + "estou no comprimido 9"',
    '- "para de me lembrar da vitamina D" / "tenho 12 na cartela"',
    '- "anota na lista: ligar pro contador" / "o que tenho nas tarefas?" / "conclui a tarefa do contador"',
    '- "sempre me avise 30 min antes", "resumo as 8h", "avise o estoque com 7 dias"', '',
    'Quando eu avisar um lembrete, use os botoes: Feito, Adiar 1h ou Adiar amanha. Na hora de tomar um remedio: Tomei ou Pular hoje.',
    'Para ver suas preferencias: /config'].join(NL);
} else if (cmd === '/config') {
  const lead = user.default_lead_minutes === null ? 'pergunto a cada vez' : (Number(user.default_lead_minutes) === 0 ? 'nunca avisar antes' : user.default_lead_minutes + ' min antes');
  text = ['Suas preferencias:', '- Resumo da manha: ' + user.summary_time, '- Aviso antes dos compromissos: ' + lead, '- Aviso de estoque: ' + user.supply_alert_days + ' dias antes de acabar (remedio: 7 dias)', '',
    'Para mudar, e so me dizer, por exemplo:', '"resumo as 8h", "sempre me avise 30 min antes", "avise o estoque com 7 dias".'].join(NL);
} else {
  text = 'Nao conheco esse comando. Use /ajuda.';
}
return [{ json: { chat_id: u.chat_id, text: text, kb: kb, rid: 0, state: '' } }];

let MODELO = 'gemini-3.5-flash-lite';
let GEN = { thinkingConfig: { thinkingLevel: 'minimal' } };
try {
  const cfg = $('Ler configuracao do modelo').first().json.modelo;
  if (cfg) {
    const s = String(cfg).trim();
    if (s.charAt(0) === '{') {
      const o = JSON.parse(s);
      if (o.modelo) { MODELO = String(o.modelo); }
      if (o.gen) { GEN = o.gen; }
    } else if (s.length > 3) { MODELO = s; }
  }
} catch (e) {}
const u = $('Normalizar update').first().json;
const user = $('Buscar usuario').first().json;
let state = null;
try { const raw = $('Ler estado da conversa').first().json.state; state = raw ? JSON.parse(raw) : null; } catch (e) { state = null; }
let hist = [];
try { const rawH = $('Ler historico da conversa').first().json.hist; hist = rawH ? JSON.parse(rawH) : []; } catch (e) { hist = []; }
const media = $input.first().json.audio_b64 || '';
const isPhoto = u.kind === 'photo';
const tz = user.timezone || 'America/Sao_Paulo';
const agora = DateTime.now().setZone(tz).setLocale('pt-BR');
const NL = String.fromCharCode(10);
const regras = [
  'Voce e o assistente pessoal de ' + user.name + ' no Telegram. Fale portugues do Brasil, curto e simpatico. Seu objetivo e deixar a vida do usuario o mais simples possivel: faca o pedido de UMA mensagem, sem pedir cadastro previo. Voce so INTERPRETA a mensagem e devolve o JSON do schema; quem executa e o sistema.',
  'CAMPOS: preencha SEMPRE title, date, time e reply. Use texto vazio ("") quando o campo nao se aplica. Os demais campos so quando se aplicam; NUNCA coloque 0 em campos numericos que o usuario nao citou (omita-os).',
  'CONTEXTO DA CONVERSA: as mensagens anteriores desta conversa (do usuario e suas respostas) vem antes da mensagem atual. Use-as para resolver referencias ("esse", "ele", "o de ontem", "as 14h" respondendo a uma pergunta sua, "sim", "isso mesmo") e para responder perguntas sobre o que foi dito antes. Se a mensagem atual completa uma pergunta sua, junte as informacoes e execute o pedido inteiro em vez de perguntar de novo. Suas respostas anteriores podem terminar com [agendado: AAAA-MM-DD HH:MM]: para "no mesmo horario", "no mesmo dia" ou "junto com o outro", copie esse date e esse time.',
  'Agora: ' + agora.toFormat('yyyy-MM-dd HH:mm') + ' (' + agora.toFormat('cccc') + '), fuso ' + tz + '. Converta datas relativas (amanha, sexta, daqui a 2 horas) a partir de agora. Um dia da semana sem data e a proxima ocorrencia futura.',
  'Itens de estoque/remedio ja cadastrados deste usuario: ' + (user.supply_items || 'nenhum') + '. Se o usuario falar de um deles (mesmo por outro nome, ou numa foto), use EXATAMENTE o nome cadastrado em item.',
  'Sempre preencha transcript com o que o usuario disse (transcreva se for audio; descreva em poucas palavras se for foto).',
  'INTENTS: create_reminder (lembrar de algo; sem duracao), create_event (compromisso na agenda: reuniao, consulta, cartorio, jantar com horario marcado), list_agenda (o que tenho hoje/amanha/semana/data), create_supply (cadastrar item de uso continuo, ex.: vitamina ou remedio, com ou sem lembrete de tomar), supply_bought (disse que comprou ou repos o item), supply_adjust (informa quantas unidades restam ou que pausou o uso por N dias), supply_taken (disse que tomou o item), supply_schedule (pede lembrete diario de tomar um item em certo horario, ou pede para parar esse lembrete), set_preference (mudar preferencias: aviso padrao antes, horario do resumo, dias de aviso do estoque), provide_time (so quando o contexto diz que o usuario esta escolhendo novo horario para adiar um lembrete), create_task (anotar na lista de tarefas ou pendencias, SEM horario: comprar leite, ligar pro contador), list_tasks (o que tenho nas tarefas ou pendencias), complete_task (concluir ou riscar uma tarefa da lista), clarify (falta informacao essencial: pergunte em reply), chat (conversa, ajuda ou pergunta sobre a propria conversa: responda em reply).',
  'REGRA DE OURO: NUNCA invente horario. Se o pedido nao tem hora exata (ex.: amanha de manha, a tarde, ou nenhuma hora), use intent=clarify e pergunte o horario exato em reply. Hora citada (14h, 2 da tarde, meio-dia=12:00) pode ser usada. Use date no formato YYYY-MM-DD e time em HH:MM (24h). Excecao: create_task, create_event, list_* e os intents de estoque seguem suas proprias regras abaixo.',
  'Se faltar so a data e a hora estiver clara, assuma hoje se a hora ainda nao passou, senao amanha.',
  'lead_minutes: SO preencha se o usuario pediu avisar antes (me lembre 1 hora antes = 60; 30 min antes = 30; um dia antes = 1440). shared=true se disser nos dois, os dois, a gente.',
  'create_event: title curto, date, time, duration_minutes (padrao 60), location se citado. list_agenda: range_start e range_end (datas inclusivas; hoje = hoje a hoje; essa semana = de hoje ate domingo).',
  'create_task: title curto da tarefa; date so se o usuario deu um prazo (sem hora). Se o usuario der um horario exato para ser avisado, e create_reminder, nao create_task. complete_task: title com as palavras principais da tarefa a concluir. list_tasks nao precisa de campos.',
  'ESTOQUE E REMEDIO: "me lembre de tomar X todo dia as 11h" ja basta: use supply_schedule com item e take_time (HH:MM); o sistema cria o item sozinho. NUNCA responda que o item nao existe e NUNCA peca para cadastrar antes. NAO pergunte a quantidade: omita units_total e units_left se o usuario nao disse. item_kind=remedio para medicamento, anticoncepcional, pilula, receita, pressao, tireoide, antibiotico; suplemento nos outros casos. Se o usuario disse tambem a quantidade (a cartela tem 30), use create_supply com item, units_total, take_time e units_per_day (padrao 1; so 1 dose por dia por enquanto). units_left = quantos restam AGORA ("tenho 12 na cartela" = 12; "estou no comprimido 9" de uma cartela de 28 = 28 - 8 = 20). supply_adjust: item e units_left e/ou pause_days (pausei por 3 dias). supply_bought: item. supply_taken: item. Para parar o lembrete: supply_schedule com stop_reminder=true. started_on so se disse quando comecou.',
  'IMAGEM: se o usuario mandar foto de embalagem, cartela ou receita de medicamento, identifique o nome em item, conte as cavidades da cartela em units_total (ex.: 28) e quantas ainda tem comprimido em units_left (se a legenda disser "estou no comprimido N", units_left = units_total - (N - 1)); use create_supply (ou supply_adjust se o item ja existe) e inclua take_time se a legenda pedir lembrete. Se for convite, cartaz ou print com data e hora, use create_event. Qualquer outra imagem: intent=chat, diga o que viu em uma frase e pergunte o que o usuario quer fazer.',
  'set_preference: pref_lead_minutes (0 = nunca avisar antes), pref_summary_time (HH:MM), pref_supply_days.'
];
if (state && state.kind === 'clarify') {
  regras.push('CONTEXTO: voce tinha perguntado algo porque a mensagem anterior do usuario estava incompleta: ' + (state.original || '') + '. A mensagem atual provavelmente complementa; combine as duas.');
}
if (state && state.kind === 'snooze') {
  regras.push('CONTEXTO: o usuario esta escolhendo o NOVO horario para adiar um lembrete. Responda intent=provide_time com date e time.');
}
const schema = {
  type: 'OBJECT',
  properties: {
    intent: { type: 'STRING', enum: ['create_reminder', 'create_event', 'list_agenda', 'create_supply', 'supply_bought', 'supply_adjust', 'supply_taken', 'supply_schedule', 'set_preference', 'provide_time', 'create_task', 'list_tasks', 'complete_task', 'clarify', 'chat'] },
    transcript: { type: 'STRING' }, title: { type: 'STRING' }, date: { type: 'STRING' }, time: { type: 'STRING' },
    duration_minutes: { type: 'INTEGER' }, location: { type: 'STRING' }, lead_minutes: { type: 'INTEGER' }, shared: { type: 'BOOLEAN' },
    range_start: { type: 'STRING' }, range_end: { type: 'STRING' },
    item: { type: 'STRING' }, item_kind: { type: 'STRING', enum: ['remedio', 'suplemento'] }, take_time: { type: 'STRING' }, stop_reminder: { type: 'BOOLEAN' },
    units_total: { type: 'INTEGER' }, units_per_day: { type: 'NUMBER' }, started_on: { type: 'STRING' }, alert_days: { type: 'INTEGER' },
    units_left: { type: 'INTEGER' }, pause_days: { type: 'INTEGER' },
    pref_lead_minutes: { type: 'INTEGER' }, pref_summary_time: { type: 'STRING' }, pref_supply_days: { type: 'INTEGER' },
    reply: { type: 'STRING' }
  },
  required: ['intent', 'transcript', 'title', 'date', 'time', 'reply']
};
const legenda = u.text || (isPhoto ? 'Imagem enviada pelo usuario, sem legenda.' : '');
let parts = [{ text: u.text }];
if (media && isPhoto) { parts = [{ inlineData: { mimeType: 'image/jpeg', data: media } }, { text: legenda }]; }
else if (media) { parts = [{ inlineData: { mimeType: 'audio/ogg', data: media } }, { text: 'Mensagem de voz do usuario. Transcreva em transcript e interprete.' }]; }
const agoraMs = Date.now();
const recentes = hist.filter(function (h) { return h && h.t && (agoraMs - h.ts) < 6 * 3600 * 1000; });
while (recentes.length && recentes[0].r !== 'user') { recentes.shift(); }
const contents = [];
recentes.forEach(function (h) {
  const role = h.r === 'model' ? 'model' : 'user';
  const prev = contents.length ? contents[contents.length - 1] : null;
  if (prev && prev.role === role) { prev.parts[0].text += NL + h.t; }
  else { contents.push({ role: role, parts: [{ text: h.t }] }); }
});
if (contents.length && contents[contents.length - 1].role === 'user') { contents.pop(); }
contents.push({ role: 'user', parts: parts });
const generationConfig = Object.assign({ responseMimeType: 'application/json', responseSchema: schema, temperature: 0 }, GEN);
return [{ json: { url: 'https://generativelanguage.googleapis.com/v1beta/models/' + MODELO + ':generateContent', modelo: MODELO,
  corpo: { systemInstruction: { parts: [{ text: regras.join(NL) }] }, contents: contents, generationConfig: generationConfig },
  state: state, history_size: recentes.length, via_audio: !!media && !isPhoto, via_photo: !!media && isPhoto } }];

const r = $input.first().json;
const u = $('Normalizar update').first().json;
const user = $('Buscar usuario').first().json;
const ctx = $('Montar pedido ao Gemini').first().json;
const tz = user.timezone || 'America/Sao_Paulo';
const base = { user_id: user.id, user_name: user.name, tz: tz, calendar_key: user.calendar_key || '', chat_id: u.chat_id, source: ctx.via_audio ? 'audio' : 'text', original_text: u.text };
let g = null;
try {
  const cand = r && r.candidates && r.candidates[0];
  const parts = cand && cand.content && Array.isArray(cand.content.parts) ? cand.content.parts : [];
  g = JSON.parse(parts.map(function (p) { return p.text; }).filter(Boolean).join(''));
} catch (e) { g = null; }
if (!g || !g.intent) {
  const errTxt = r && r.error ? String(r.error.message || '') + ' ' + String(r.error.description || '') : '';
  const quota = /quota|too many requests|rate limit|429/i.test(errTxt);
  const modeloOff = /no longer available|not found|could not be found/i.test(errTxt);
  let msg = 'Tive um problema para entender agora. Pode tentar de novo em instantes?';
  if (quota) { msg = 'Atingi o limite diario de uso do Gemini (plano gratuito). Volto a responder quando a cota renovar ou quando o plano for ampliado.'; }
  else if (modeloOff) { msg = 'O modelo do Gemini configurado (' + ctx.modelo + ') nao esta disponivel. Preciso que o administrador troque o modelo.'; }
  return [{ json: Object.assign({}, base, { intent: 'chat', llm_error: true, llm_detail: errTxt.slice(0, 300), reply: msg }) }];
}
const out = Object.assign({}, base, g);
['title', 'date', 'time', 'reply', 'item', 'location'].forEach(function (k) { if (out[k] === null || out[k] === undefined) { out[k] = ''; } });
if (typeof out.units_total === 'number' && out.units_total <= 0) { delete out.units_total; }
if (typeof out.units_per_day === 'number' && out.units_per_day <= 0) { delete out.units_per_day; }
if (typeof out.units_left === 'number' && out.units_left < 0) { delete out.units_left; }
if (typeof out.duration_minutes === 'number' && out.duration_minutes <= 0) { delete out.duration_minutes; }
if (typeof out.lead_minutes === 'number' && out.lead_minutes < 0) { delete out.lead_minutes; }
const now = DateTime.now().setZone(tz);
const okDate = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;
const okTime = /^[0-9]{1,2}:[0-9]{2}$/;
const st = ctx.state;
if (st && st.kind === 'snooze' && (g.intent === 'provide_time' || g.intent === 'create_reminder' || g.intent === 'clarify') && (g.time || /[0-9]/.test(String(u.text || '')))) {
  out.intent = 'provide_time'; out.rid = st.reminder_id;
}
const needsTime = ['create_reminder', 'create_event', 'provide_time'].indexOf(out.intent) >= 0;
if (needsTime) {
  const txt = String(out.transcript || u.text || '').toLowerCase();
  let tm = out.time && okTime.test(out.time) ? out.time : '';
  let dd = out.date && okDate.test(out.date) ? out.date : '';
  let ultimo = null;
  try {
    const rawH = $('Ler historico da conversa').first().json.hist;
    const hh = rawH ? JSON.parse(rawH) : [];
    for (let i = hh.length - 1; i >= 0 && !ultimo; i--) {
      const m = /\[agendado: ([0-9-]{10}) ([0-9:]{5})\]/.exec(String(hh[i].t || ''));
      if (m) { ultimo = { d: m[1], t: m[2] }; }
    }
  } catch (e) { ultimo = null; }
  if (!tm) {
    let m1 = /(?:as|às|a)[ ]*([0-9]{1,2})[ ]*(?:h|:)[ ]*([0-9]{2})?/i.exec(txt);
    if (!m1) { m1 = /([0-9]{1,2})[ ]*(?:h|:)([0-9]{2})?/i.exec(txt); }
    if (m1) { tm = m1[1] + ':' + (m1[2] ? m1[2] : '00'); }
  }
  const mesmo = /mesm[oa][ ]*(horario|hora|dia)/i.test(txt) || /mesm[oa][ ]*(horário)/i.test(txt);
  if (!tm && mesmo && ultimo) { tm = ultimo.t; if (!dd) { dd = ultimo.d; } }
  if (!dd) {
    if (txt.indexOf('depois de amanh') >= 0) { dd = now.plus({ days: 2 }).toFormat('yyyy-MM-dd'); }
    else if (txt.indexOf('amanh') >= 0) { dd = now.plus({ days: 1 }).toFormat('yyyy-MM-dd'); }
    else if (txt.indexOf('hoje') >= 0) { dd = now.toFormat('yyyy-MM-dd'); }
    else if (mesmo && ultimo) { dd = ultimo.d; }
  }
  if (!tm) {
    out.intent = 'clarify'; out.reply = out.reply || 'Que horas? Me diga o horario exato.';
  } else {
    const hhmm = tm.length === 4 ? '0' + tm : tm;
    let d = dd || null;
    if (!d) { const t = DateTime.fromISO(now.toFormat('yyyy-MM-dd') + 'T' + hhmm, { zone: tz }); d = (t > now ? t : t.plus({ days: 1 })).toFormat('yyyy-MM-dd'); }
    const due = DateTime.fromISO(d + 'T' + hhmm, { zone: tz });
    if (!due.isValid) { out.intent = 'clarify'; out.reply = 'Nao entendi a data e a hora. Pode repetir?'; }
    else if (due <= now) { out.intent = 'clarify'; out.reply = 'Esse horario ja passou. Para quando eu agendo?'; }
    else {
      out.due_iso = due.toISO(); out.due_label = due.setLocale('pt-BR').toFormat("ccc dd/MM 'as' HH:mm");
      out.end_iso = due.plus({ minutes: out.duration_minutes || 60 }).toISO();
    }
  }
}
if (out.intent === 'list_agenda') {
  const today = now.toFormat('yyyy-MM-dd');
  const a = out.range_start && okDate.test(out.range_start) ? out.range_start : today;
  const b = out.range_end && okDate.test(out.range_end) ? out.range_end : a;
  const ini = DateTime.fromISO(a, { zone: tz }).startOf('day');
  const fim = DateTime.fromISO(b, { zone: tz }).startOf('day').plus({ days: 1 });
  out.time_min = ini.toISO(); out.time_max = fim.toISO();
  out.range_label = a === b ? ini.toFormat('dd/MM') : ini.toFormat('dd/MM') + ' a ' + fim.minus({ days: 1 }).toFormat('dd/MM');
}
let tt = '';
if (out.take_time && okTime.test(out.take_time)) { tt = out.take_time.length === 4 ? '0' + out.take_time : out.take_time; }
if (!tt && (out.intent === 'create_supply' || out.intent === 'supply_schedule') && out.time && okTime.test(out.time)) { tt = out.time.length === 4 ? '0' + out.time : out.time; }
out.take_time = tt;
out.item_kind = out.item_kind === 'remedio' ? 'remedio' : '';
if (out.intent === 'supply_schedule' && out.stop_reminder !== true && !tt) {
  out.intent = 'clarify'; out.reply = out.reply || 'A que horas voce quer ser lembrado de tomar?';
}
out.task_due = (out.intent === 'create_task' && out.date && okDate.test(out.date)) ? out.date : '';
out.task_action = out.intent === 'create_task' ? 'add' : (out.intent === 'list_tasks' ? 'list' : (out.intent === 'complete_task' ? 'complete' : ''));
out.lead_str = (out.lead_minutes === undefined || out.lead_minutes === null) ? '' : String(out.lead_minutes);
out.shared = out.shared === true;
out.title = out.title || '';
return [{ json: out }];

const a = $('Interpretar resposta').first().json;
const r = $input.first().json.r || {};
let text = 'Lembrete criado: "' + a.title + '" - ' + a.due_label + (a.shared ? ' (para voces dois)' : '') + '.';
let kb = 'none';
